input.command:
cd "$(cat /tmp/tk036_snap)" && python -m radon cc -nD .claude tools 2>&1 | head -3; python -m radon cc -nD .claude tools 2>&1 | grep -c " - [DEF] "; python -m radon cc -nE .claude tools | wc -l; find .claude tools -name "*.py" ! -name "test_*" ! -name conftest.py | wc -l; find .claude tools -name "*.py" ! -name "test_*" ! -name conftest.py | xargs wc -l | sort -n | tail -3; python - <<'EOF'
import ast,pathlib
best=[];fs=[p for p in list(pathlib.Path('.claude').rglob('*.py'))+list(pathlib.Path('tools').rglob('*.py')) if not p.name.startswith('test_') and p.name!='conftest.py']
for p in fs:
    for f in ast.walk(ast.parse(p.read_text(encoding='utf-8'))):
        if isinstance(f,(ast.FunctionDef,ast.AsyncFunctionDef)): best.append((f.end_lineno-f.lineno+1,p.name,f.name))
best.sort(reverse=True);print(len(fs),best[:2],sum(b[0]>100 for b in best))
EOF
cd "C:/visual projects/role-play-vibing" && git diff --stat ba2ef65 origin/main -- .claude tools | tail -5

